-- The tuple header's size field is asked as each row is read, before the sort: a row past
-- 8 191 bytes is refused ahead of the duplicate beside it.
-- @setup
CREATE TABLE t (a text);
INSERT INTO t VALUES (''), ('x'), ('x');
-- @test
-- @expect-error: the size field before the duplicate
-- @expect-message
-- @profile-lock
CREATE UNIQUE INDEX t_i ON t (a);
